```swift
struct Label {
    static let prefix = "item:"
    var text: String
    static func decorate(_ text: String) -> String {
        return prefix + text
    }
}
var first = Label(text: "map")
let second = Label(text: "lamp")
first.text = "book"
print(Label.prefix)
print(Label.decorate(first.text))
print(Label.decorate(second.text))
```
This prints item:, item:book, and item:lamp. Changing first.text to book leaves second.text as lamp.
